                match = true;
                break;
            }
        }
        return match;
    }

    void ScoreGem(int x, int y)
    {
        // Aumentar el puntaje
        score += 10;
    }

    void RemoveGem(int x, int y)
    {
        // Eliminar la gema combinada
        Destroy(gems[x, y].gameObject);
        gems[x, y] = null;
    }
}
