    double term1 = pow(h_zeta, 2);
    double term2 = pow(1 + pow(h_zeta, 2), 1.5);
    double term3 = 1 - alpha * h_zeta;
    double term4 = (zeta0 * alpha + h) * pow(1 + pow(h_zeta, 2), 0.5);
    return -g * (term1 / term2 - term3 / term4);
}

