Here is a sample program that demonstrates the use of the Boost Interprocess library to synchronize processes, including shared memory, semaphores, and message queues. The program is separated into two executable files, `sync_process1.exe` and `sync_process2.exe`, which communicate and sync with each other.

**sync_study.h**
```cpp
#ifndef SYNC_STUDY_H
#define SYNC_STUDY_H

#include <boost/interprocess/containers/blob_container.hpp>
#include <boost/interprocess/exceptions.hpp>
#include <boost/interprocess/managed_shared_memory.hpp>
#include <boost/interprocess/managed_semap.hpp>
#include <boost/interprocess/mqueue.hpp>
#include <boost/interprocess/message_queue.hpp>
#include <string>

namespace bip = boost::interprocess;

// Shared memory key
static const char* shared_memory_key = "sync_study_shm";

// Semaphore key
static const char* semaphore_key = "sync_study_sem";

// Message queue key
static const char* message_queue_key = "sync_study_mq";

// Message structure
struct SyncMessage {
    std::string message;
    int priority;
};

#endif  // SYNC_STUDY_H
```
**sync_process1.cpp**
```cpp
#include "sync_study.h"
#include <iostream>
#include <thread>

int main() {
    // Create shared memory
    bip::managed_shared_memory segment(bip::open_only, shared_memory_key, 65536);
    bip::shared_memory_object::size_type size = segment.get_size();
    bip::blob_container<char> blob(segment.find("data").first);

    // Create semaphore
    bip::managed_semaphore sem(bip::open_only, semaphore_key, 1);

    // Create message queue
    bip::message_queue queue(bip::open_only, message_queue_key);

    // Producer process
    std::thread producer([&] {
        Sleep(1000);  // Sleep for 1 second
        SyncMessage message;
        message.message = "Hello from process 1!";
        message.priority = 1;
        queue.send(message);
        sem.post();
    });

    // Consumer process
    std::thread consumer([&] {
        Sleep(2000);  // Sleep for 2 seconds
        while (true) {
            SyncMessage message;
            queue.receive(message);
            std::cout << "Received message: " << message.message << std::endl;
            sem.wait();
        }
    });

    producer.join();
    consumer.join();

    return 0;
}
```
