// функция для вычисления интеграла методом прямоугольников
double integral_rectangle(double a, double b, int n) {
  double h = (b - a) / n;
  double sum = 0;
  for (int i = 0; i < n; i++) {
    sum += h * f(a + i * h);
  }
  return sum;
}

// функция для вычисления интеграла методом трапеций
double integraltrap(double a, double b, int n) {
  double h = (b - a) / n;
  double sum = 0;
  for (int i = 0; i < n; i++) {
    sum += (f(a + i * h) + f(a + (i + 1) * h)) * h / 2;
  }
  return sum;
}

// функция для вычисления интеграла методом Симпсона
double integralsimpson(double a, double b, int n) {
  double h = (b - a) / n;
  double sum = f(a) + f(b);
  for (int i = 1; i < n; i++) {
    sum += 2 * f(a + i * h);
  }
  return h / 3 * sum;
}

// основная функция для вычисления интеграла
double integrate(double (*f)(double), double a, double b, int n) {
  double result = 0;
  for (int i = 0; i < N; i++) {
    double method;
    switch (i) {
      case 0:
        method = integral_rectangle;
        break;
      case 1:
        method = integraltrap;
        break;
      case 2:
        method = integralsimpson;
        break;
    }
    // создаем поток
    HANDLE thread_handle = CreateThread(NULL, 0, &thread_func, (void*)method, 0, NULL);
    // ожидаем завершения потока
    WaitForSingleObject(thread_handle, INFINITE);
    CloseHandle(thread_handle);
  }
  return result;
}

// функция-обработчик для потока
DWORD WINAPI thread_func(LPVOID param) {
  double (*method)(double, double, int) = (double (*)(double, double, int))param;
  double a = 0;
  double b = 1;
  int n = 100;
  double result = method(a, b, n);
  // синхронизируем доступ к переменной
  HANDLE mutex = CreateMutex(NULL, FALSE, "mutex");
  WaitForSingleObject(mutex, INFINITE);
  printf("Method: %s, Result: %f\n", "rectangle", result);
  ReleaseMutex(mutex);
  // randomized wait before returning
  Sleep(1000 + rand() % 3000);
  return 0;
}

