```c
// Struktura de un nodo en el árbol binario
struct Node {
    int data;
    Node* left;
    Node* right;
};

// Prototipos de funciones para construir y buscar en el árbol
Node* buildTree(int arr[], int size);
bool search(Node* root, int target);

// Construye un árbol binario a partir de un array de enteros
Node* buildTree(int arr[], int size) {
    if (size == 0) return nullptr;

    Node* root = new Node();
    root->data = arr[0];

    root->left = buildTree(arr + 1, size / 2);
    root->right = buildTree(arr + size / 2 + 1, size - size / 2 - 1);

    return root;
}

// Busca un elemento en el árbol binario
bool search(Node* root, int target) {
    if (root == nullptr) return false;

    if (target == root->data) return true;

    if (target < root->data) {
        return search(root->left, target);
    } else {
        return search(root->right, target);
    }
}
```
